custom.css:
/* Faden & Form – Bewegung ohne Einblend-Show.
   Parallaxe und Scroll-Bewegung laufen über CSS scroll-driven animations:
   kein JavaScript, nur transform (GPU), abgeschaltet bei prefers-reduced-motion. */

:root { --ff-stitch: repeating-linear-gradient(90deg, currentColor 0 10px, transparent 10px 18px); }

/* Nahtlinie als Gestaltungsmotiv unter Kicker-Texten */
.wa-kicker, [data-kicker] { position: relative; padding-bottom: .6rem; }
.wa-kicker::after, [data-kicker]::after {
  content: ""; position: absolute; left: 0; bottom: 0; width: 64px; height: 2px;
  background: var(--ff-stitch); color: var(--color-accent); opacity: .9;
}

/* Hover: Karten heben sich leicht, Bilder zoomen sanft */
.wa-card, .wa-cards__item, .wa-pricing__plan, .wa-steps__item {
  transition: transform .35s cubic-bezier(.2,.7,.2,1), box-shadow .35s ease;
}
.wa-card:hover, .wa-cards__item:hover, .wa-pricing__plan:hover, .wa-steps__item:hover {
  transform: translateY(-6px);
  box-shadow: 0 18px 40px -18px rgba(35,70,56,.35);
}
.wa-gallery__item, .wa-imagetext__media, .wa-image { overflow: hidden; }
.wa-gallery__item img, .wa-imagetext__media img, .wa-image img {
  transition: transform .8s cubic-bezier(.2,.7,.2,1);
}
.wa-gallery__item:hover img, .wa-imagetext__media:hover img { transform: scale(1.05); }

.wa-btn { transition: transform .25s ease, background-color .25s ease, color .25s ease, box-shadow .25s ease; }
.wa-btn:hover { transform: translateY(-2px); }

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    /* Parallaxe: Medien wandern langsamer als der Inhalt */
    .ff-parallax .wa-imagetext__media img,
    .ff-parallax .wa-hero__media img,
    .ff-parallax .wa-hero__bg {
      animation: ff-parallax linear both;
      animation-timeline: view();
      animation-range: cover;
      will-change: transform;
    }
    @keyframes ff-parallax {
      from { transform: translateY(-8%) scale(1.12); }
      to   { transform: translateY(8%)  scale(1.12); }
    }

    /* Leichtes Gegeneinander-Gleiten von Spalten */
    .ff-drift > :nth-child(odd)  { animation: ff-drift-up linear both;   animation-timeline: view(); animation-range: cover; }
    .ff-drift > :nth-child(even) { animation: ff-drift-down linear both; animation-timeline: view(); animation-range: cover; }
    @keyframes ff-drift-up   { from { transform: translateY(24px); }  to { transform: translateY(-24px); } }
    @keyframes ff-drift-down { from { transform: translateY(-12px); } to { transform: translateY(12px); } }

    /* Grosse Zahlen gleiten seitlich mit dem Scrollen */
    .ff-slide .wa-stats__item { animation: ff-slide linear both; animation-timeline: view(); animation-range: entry 0% cover 60%; }
    @keyframes ff-slide { from { transform: translateX(-18px); } to { transform: translateX(0); } }
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
